      "Player offensive roles",
      "Play type classification (cuts, drives)",
      "Player role transferability",
      "Player impact measurement"
    ],
    "methodological_questions": [
      "How to define and measure 'cut-heavy' and 'drive-heavy' players from play-type data?",
      "How to quantify the 'travel' or transferability of a player's role?",
      "What metrics are suitable for assessing player effectiveness across different team contexts?",
      "How to control for confounding variables when evaluating player role transferability?"
    ],
    "query": "Player offensive role transferability, specifically comparing cut-heavy versus drive-heavy player effectiveness across teams or seasons using play-type data."
  }
}

